/* xx_wpk_extractor.c - search raw data for WPK.
 *
 * Scans for:
 *   03 24 01 01 at +0  (".$..")
 *   03 24 33 01 at +0  (".$3.")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the wpk reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/wpk/xx_wpk.h"

static const uint8_t k_anchor0[] = { 0x03, 0x24, 0x01, 0x01 };
static const uint8_t k_anchor1[] = { 0x03, 0x24, 0x33, 0x01 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
    { k_anchor1, sizeof(k_anchor1), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_WPK };

static Abstractformat *xx_wpk_search_open(xx_io_device *window) {
    xx_wpk *reader = xx_wpk_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_wpk_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_wpk_free((xx_wpk *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_wpk_search_open, xx_wpk_search_close
};

static xx_format_search_state *xx_wpk_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_wpk_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_wpk_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_wpk_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_wpk_extractor = {
    xx_wpk_create_format_search,
    xx_wpk_get_current_format_info,
    xx_wpk_format_search_find_next,
    xx_wpk_free_format_search
};
